def largestRectangleArea(h):
    stack, ans = [], 0
    h.append(0)  # 哨兵：收尾清栈
    for i, cur in enumerate(h):
        while stack and h[stack[-1]] >= cur:
            ht = h[stack.pop()]
            left = stack[-1] if stack else -1
            ans = max(ans, ht * (i - left - 1))
        stack.append(i)
    return ans

def search(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
